const int maxn = 5005; 
const long long INF = (1LL<<62); 

int n, g;
int k_exp;
long long a[maxn]; 
long long pref1[maxn]; 
long long pref2[maxn]; 

long long dp[maxn][maxn]; 

inline long long sum1(int l, int r){ return pref1[r] - pref1[l-1]; }

inline long long sum2(int l, int r){ return pref2[r] - pref2[l-1]; }

long long cost_k1(int l, int r){
    int m = (l + r) >> 1;

    long long left = a[m] * (long long)(m - l + 1) - sum1(l, m);

    long long right = sum1(m + 1, r) - a[m] * (long long)(r - m);
    return left + right;
}

long long cost_k2(int l, int r){
    int len = r - l + 1;
    long long S1 = sum1(l,r);
    long long S2 = sum2(l,r);
    double mean = (double)S1 / (double)len;
    long long v1 = (long long)floor(mean);
    long long v2 = (long long)ceil(mean);

    auto eval = [&](long long v)->long long{
        return S2 - 2*v*S1 + (long long)len * v * v;
    };
    return min(eval(v1), eval(v2));
}

inline long long cost(int l, int r){
    if(l > r) return 0;
    if(k_exp == 1) return cost_k1(l,r);
    if(k_exp == 2) return cost_k2(l,r);

    long long best = INF;
    for(long long v = a[l]; v <= a[r]; ++v){
        long double cur = 0;
        for(int s=l;s<=r;++s){
            long double diff = fabsl((long double)a[s] - (long double)v);
            long double term = 1;
            for(int t=0;t<k_exp;++t) term *= diff;
            cur += term;
            if(cur >= (long double)best) { 
                cur = (long double)best; 
                break;
            }
        }
        if(cur < (long double)best) best = (long long) llround(cur);
    }
    return best;
}

void cal(int g_, int L, int R, int optL, int optR){
    if(L > R) return;

    int mid = (L + R) >> 1;
    pair<long long, int> best = {INF, -1};

    int start = max(1, optL);
    int endd  = min(mid, optR);

    for(int i = start; i <= endd; ++i){

        if (dp[g_-1][i-1] == INF) continue; 

        long long val = dp[g_-1][i-1] + cost(i, mid);

        if(val < best.first){
            best = {val, i};
        }
    }

    dp[g_][mid] = best.first;
    int opt = best.second;
    if(L == R) return;
    cal(g_, L, mid - 1, optL, opt);
    cal(g_, mid + 1, R, opt, optR);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> g >> k_exp;

    if (n > maxn - 1 || g > maxn - 1) {

    }

    for(int i=1; i<=n; i++) {
        cin >> a[i];
    }

    pref1[0] = 0;
    pref2[0] = 0;
    for(int i=1; i<=n; i++){
        pref1[i] = pref1[i-1] + a[i];
        pref2[i] = pref2[i-1] + a[i] * a[i];
    }

    for(int g_ = 0; g_ <= g; ++g_) {
        for(int i = 0; i <= n; ++i) {
            dp[g_][i] = INF;
        }
    }

    dp[0][0] = 0;

    for(int g_=1; g_<=g; ++g_){
        cal(g_, 1, n, 1, n);
        
    }

    cout << dp[g][n];
}